	private static float SrgbToLinear(float c)
	{
		if (!(c <= 0.04045f))
		{
			return (float)Math.Pow((c + 0.055f) / 1.055f, 2.4000000953674316);
		}
		return c / 12.92f;
	}

	private static float LinearToSrgb(float c)
	{
		if (!(c <= 0.0031308f))
		{
