		{
			vFacing = Math.Max((sbyte)(minLaunchAngle.Angle >> 2), (sbyte)0);
			speed = maxLaunchSpeed;
			return;
		}
		vFacing = (sbyte)new WVec(-wVec.Z, -horizontalLength, 0).Yaw.Facing;
		if (vFacing == -1)
