	}

	private static int BisectionSearch(int lowerBound, int upperBound, Func<int, bool> testCriterion)
	{
		while (upperBound - lowerBound > 1)
		{
			int num = (upperBound + lowerBound) / 2;
			if (testCriterion(num))
			{
