		{
			targetPassedBy = true;
		}
		if (info.Jammable && world.ActorsWithTrait<JamsMissiles>().Any(JammedBy))
		{
			num2 = hFacing + world.SharedRandom.Next(-info.JammedDiversionRange, info.JammedDiversionRange + 1);
			desiredFacing = vFacing + world.SharedRandom.Next(-info.JammedDiversionRange, info.JammedDiversionRange + 1);
		}
		else if (!args.GuidedTarget.IsValidFor(args.SourceActor))
		{
			num2 = hFacing;
		}
		hFacing = Util.TickFacing(hFacing, num2, info.HorizontalRateOfTurn.Facing);
		vFacing = Util.TickFacing(vFacing, desiredFacing, info.VerticalRateOfTurn.Facing);
		return new WVec(0, -1024 * speed, 0).Rotate(new WRot(WAngle.FromFacing(vFacing), WAngle.Zero, WAngle.Zero)).Rotate(new WRot(WAngle.Zero, WAngle.Zero, WAngle.FromFacing(hFacing))) / 1024;
	}

	public void Tick(World world)
	{
		ticks++;
		anim?.Tick();
		if (ticks == info.HomingActivationDelay + 1)
		{
			state = States.Homing;
			speed = velocity.Length;
			loopRadius = LoopRadius(speed, info.VerticalRateOfTurn.Facing);
		}
		if (rangeLimit >= WDist.Zero && distanceCovered > rangeLimit)
		{
			state = States.Freefall;
			velocity = new WVec(0, -speed, 0).Rotate(new WRot(WAngle.FromFacing(vFacing), WAngle.Zero, WAngle.Zero)).Rotate(new WRot(WAngle.Zero, WAngle.Zero, WAngle.FromFacing(hFacing)));
		}
		WPos a = targetPosition;
		if (args.GuidedTarget.IsValidFor(args.SourceActor) && lockOn)
		{
			a = (args.Weapon.TargetActorCenter ? args.GuidedTarget.CenterPosition : args.GuidedTarget.Positions.ClosestToIgnoringPath(args.Source)) + new WVec(WDist.Zero, WDist.Zero, info.AirburstAltitude);
		}
		WAngle wAngle = ((tarVel.HorizontalLengthSquared != 0L) ? tarVel.Yaw : WAngle.FromFacing(hFacing));
		tarVel = a - targetPosition;
		WAngle wAngle2 = ((tarVel.HorizontalLengthSquared != 0L) ? tarVel.Yaw : WAngle.FromFacing(hFacing));
		predVel = tarVel.Rotate(WRot.FromYaw(wAngle2 - wAngle));
		targetPosition = a;
		WVec tarDistVec = targetPosition + offset - pos;
		int length = tarDistVec.Length;
		int horizontalLength = tarDistVec.HorizontalLength;
		WVec move;
		if (state == States.Freefall)
		{
			move = FreefallTick();
		}
		else
		{
			move = HomingTick(world, in tarDistVec, horizontalLength);
		}
		renderFacing = new WVec(move.X, move.Y - move.Z, 0).Yaw;
		WPos start = pos;
		if (info.AllowSnapping && state != States.Freefall && length < move.Length)
		{
			pos = targetPosition + offset;
		}
		else
		{
			pos += move;
		}
		bool flag = false;
		if (info.Blockable && BlocksProjectiles.AnyBlockingActorsBetween(world, args.SourceActor.Owner, start, pos, info.Width, out var hit))
		{
			pos = hit;
			flag = true;
		}
		if (!string.IsNullOrEmpty(info.TrailImage) && --ticksToNextSmoke < 0 && (state != States.Freefall || info.TrailWhenDeactivated))
		{
			world.AddFrameEndTask((World w) =>
			{
				w.Add(new SpriteEffect(pos - ILSpyHelper_AsRefReadOnly(3 * move / 2), renderFacing, w, info.TrailImage, info.TrailSequences.Random(world.SharedRandom), trailPalette));
				static ref readonly T ILSpyHelper_AsRefReadOnly<T>(in T temp)
				{
					//ILSpy generated this function to help ensure overload resolution can pick the overload using 'in'
					return ref temp;
				}
			});
			ticksToNextSmoke = info.TrailInterval;
		}
		if (info.ContrailLength > 0)
		{
			contrail.Update(pos);
		}
		distanceCovered += new WDist(speed);
		CPos cell = world.Map.CellContaining(pos);
		WDist wDist = world.Map.DistanceAboveTerrain(pos);
		if (flag | (wDist.Length < 0 || length < info.CloseEnough.Length || (info.ExplodeWhenEmpty && rangeLimit >= WDist.Zero && distanceCovered > rangeLimit) || !world.Map.Contains(cell) || (!string.IsNullOrEmpty(info.BoundToTerrainType) && world.Map.GetTerrainInfo(cell).Type != info.BoundToTerrainType) || (wDist.Length < info.AirburstAltitude.Length && horizontalLength < info.CloseEnough.Length)))
		{
			Explode(world);
		}
	}

	private void Explode(World world)
	{
		if (info.ContrailLength > 0)
		{
			world.AddFrameEndTask((World w) =>
			{
				w.Add(new ContrailFader(pos, contrail));
			});
		}
		world.AddFrameEndTask((World w) =>
		{
			w.Remove(this);
		});
		if (ticks > info.Arm)
		{
			WarheadArgs warheadArgs = new WarheadArgs(args)
			{
				ImpactOrientation = new WRot(WAngle.Zero, WAngle.FromFacing(vFacing), WAngle.FromFacing(hFacing)),
				ImpactPosition = pos
			};
			args.Weapon.Impact(Target.FromPos(pos), warheadArgs);
		}
	}

	public IEnumerable<IRenderable> Render(WorldRenderer wr)
	{
		if (info.ContrailLength > 0)
		{
			yield return contrail;
		}
		if (anim == null)
		{
			yield break;
		}
		World world = args.SourceActor.World;
		if (world.FogObscures(pos))
		{
			yield break;
		}
		string text = info.Palette;
		if (text != null && info.IsPlayerPalette)
		{
			text += args.SourceActor.Owner.InternalName;
		}
		PaletteReference palette = wr.Palette(text);
		IRenderable[] array;
		if (info.Shadow)
		{
			WDist wDist = world.Map.DistanceAboveTerrain(pos);
			WPos wPos = pos - ILSpyHelper_AsRefReadOnly(new WVec(0, 0, wDist.Length));
			array = anim.Render(wPos, palette);
			foreach (IRenderable renderable in array)
			{
				yield return ((IModifyableRenderable)renderable).WithTint(in shadowColor, ((IModifyableRenderable)renderable).TintModifiers | TintModifiers.ReplaceColor).WithAlpha(shadowAlpha);
			}
		}
		array = anim.Render(pos, palette);
		for (int i = 0; i < array.Length; i++)
		{
			yield return array[i];
		}
		static ref readonly T ILSpyHelper_AsRefReadOnly<T>(in T temp)
		{
			//ILSpy generated this function to help ensure overload resolution can pick the overload using 'in'
			return ref temp;
		}
	}
}

