	{
		File.WriteAllBytes(path, Save());
	}

	private static byte Paeth(byte a, byte b, byte c)
	{
	    int p = a + b - c;
	    int pa = Math.Abs(p - a);
	    int pb = Math.Abs(p - b);
	    int pc = Math.Abs(p - c);
	    if (pa <= pb && pa <= pc)
	    {
