	}

	public override int GetHashCode()
	{
		return (int)(argb ^ argb);
	}

	public override string ToString()
	{
		scoped Span<byte> span;
		if (A == byte.MaxValue)
		{
			span = stackalloc byte[3] { R, G, B };
			return CryptoUtil.ToHex(span);
		}
		span = stackalloc byte[4] { R, G, B, A };
		return CryptoUtil.ToHex(span);
	}
}

