	{
		speed = (speed + sign * info.Acceleration.Length).Clamp(0, maxSpeed);
		loopRadius = LoopRadius(speed, info.VerticalRateOfTurn.Facing);
	}

	private WVec FreefallTick()
	{
		WVec result = velocity + gravity / 2;
		velocity += gravity;
		int num = maxSpeed * 1024 / velocity.Length;
		if (num < 1024)
		{
			velocity = velocity * num / 1024;
		}
		return result;
	}

	private void InclineLookahead(World world, int distCheck, out int predClfHgt, out int predClfDist, out int lastHtChg, out int lastHt)
	{
		predClfHgt = 0;
		predClfDist = 0;
		lastHtChg = 0;
		lastHt = 0;
		WVec b = new WVec(0, -32, 0).Rotate(new WRot(WAngle.Zero, WAngle.Zero, WAngle.FromFacing(hFacing)));
		int val = loopRadius * 4;
		WPos a = pos;
		int num = 0;
		int num2 = Math.Min(val, distCheck) / 32;
		int num3 = 0;
		for (int i = 0; i <= num2; i++)
		{
			a += b;
			if (world.Map.Contains(world.Map.CellContaining(a)))
			{
				int num4 = world.Map.Height[world.Map.CellContaining(a)] * 512;
				num += 32;
				if (num4 > predClfHgt)
				{
					predClfHgt = num4;
					predClfDist = num;
				}
				if (num3 != num4)
				{
					lastHtChg = num;
					lastHt = num3;
					num3 = num4;
				}
				continue;
			}
			break;
		}
	}

	private int IncreaseAltitude(int predClfDist, int diffClfMslHgt, int relTarHorDist, int vFacing)
	{
		int num = vFacing;
		if ((sbyte)vFacing < 0)
		{
			num = info.VerticalRateOfTurn.Facing;
		}
		else if (IsNearInclineTop(vFacing, loopRadius, predClfDist) && WillClimbAroundInclineTop(vFacing, loopRadius, predClfDist, diffClfMslHgt))
		{
			num = 0;
		}
		else if (!WillClimbWithinDistance(vFacing, loopRadius, predClfDist, diffClfMslHgt))
		{
			for (int num2 = Math.Min(vFacing + info.VerticalRateOfTurn.Facing - 1, 63); num2 >= vFacing; num2--)
			{
				if (!WillClimbWithinDistance(num2, loopRadius, predClfDist, diffClfMslHgt) && (predClfDist > loopRadius * (1024 - WAngle.FromFacing(num2).Sin()) / 1024 || !WillClimbAroundInclineTop(num2, loopRadius, predClfDist, diffClfMslHgt)))
				{
					num = num2 + 1;
					break;
				}
			}
		}
		int num3 = loopRadius * (1024 - WAngle.FromFacing(vFacing).Cos()) / 1024 - diffClfMslHgt;
		if (info.Acceleration.Length != 0 && ((num != 0 && (predClfDist <= loopRadius * (1024 - WAngle.FromFacing(vFacing).Sin()) / 1024 || relTarHorDist <= 2 * loopRadius * (2048 - WAngle.FromFacing(vFacing).Sin()) / 1024 - predClfDist)) || (num == 0 && relTarHorDist <= loopRadius * WAngle.FromFacing(vFacing).Sin() / 1024 + Exts.ISqrt(num3 * (2 * loopRadius - num3)))))
		{
			ChangeSpeed(-1);
		}
		return num;
	}

	private int HomingInnerTick(int predClfDist, int diffClfMslHgt, int relTarHorDist, int lastHtChg, int lastHt, int relTarHgt, int vFacing, bool targetPassedBy)
	{
		int num;
		if (info.TerrainHeightAware && diffClfMslHgt >= 0 && !allowPassBy)
		{
			num = IncreaseAltitude(predClfDist, diffClfMslHgt, relTarHorDist, vFacing);
		}
		else if (relTarHorDist <= 3 * loopRadius || state == States.Hitting)
		{
			state = States.Hitting;
			if (lastHt >= targetPosition.Z)
			{
				allowPassBy = true;
			}
			if (!allowPassBy && ((lastHt < targetPosition.Z) | targetPassedBy))
			{
				WVec wVec = new WVec(-relTarHgt, -relTarHorDist, 0);
				num = (((sbyte)wVec.HorizontalLengthSquared != 0) ? wVec.Yaw.Facing : vFacing);
				if (num == -1)
				{
					num = 0;
				}
				if (targetPassedBy)
				{
					num = num.Clamp(-info.VerticalRateOfTurn.Facing, info.VerticalRateOfTurn.Facing);
				}
				else if (lastHt == 0)
				{
					int num2 = (loopRadius * WAngle.FromFacing(vFacing).Cos() / 1024 - Math.Abs(relTarHgt)).Clamp(0, loopRadius);
					int num3 = Exts.ISqrt(loopRadius * loopRadius - num2 * num2);
					int num4 = loopRadius * WAngle.FromFacing(vFacing).Sin() / 1024;
					if (relTarHorDist <= num3 - Math.Sign(relTarHgt) * num4)
					{
						ChangeSpeed(-1);
					}
					else
					{
						ChangeSpeed();
					}
				}
			}
			else if (allowPassBy || (lastHt != 0 && relTarHorDist - lastHtChg < loopRadius))
			{
				allowPassBy = true;
				WVec b = new WVec(loopRadius, 0, 0).Rotate(new WRot(WAngle.Zero, WAngle.Zero, WAngle.FromFacing(64 - vFacing)));
				WVec wVec2 = new WVec(lastHtChg, lastHt - pos.Z, 0) - b;
				if (!targetPassedBy)
				{
					if (relTarHorDist > 2 * loopRadius)
					{
						int num5 = relTarHorDist - lastHtChg;
						if (num5 < 0)
						{
							num5 = 0;
						}
						if (num5 > 2 * loopRadius)
						{
							return 0;
						}
						int num6 = loopRadius - Exts.ISqrt(num5 * (2 * loopRadius - num5)) - (pos.Z - lastHt);
						num = ((num6 > loopRadius * (1024 - WAngle.FromFacing(vFacing).Cos()) / 1024) ? (WAngle.ArcTan(Exts.ISqrt(num6 * (2 * loopRadius - num6)), loopRadius - num6).Angle >> 2) : 0);
					}
					else if (info.TerrainHeightAware && wVec2.Length > loopRadius && lastHt > targetPosition.Z)
					{
						int i;
						for (i = vFacing + 1; i <= vFacing + info.VerticalRateOfTurn.Facing - 1; i++)
						{
							b = new WVec(loopRadius, 0, 0).Rotate(new WRot(WAngle.Zero, WAngle.Zero, WAngle.FromFacing(64 - i)));
							if ((new WVec(lastHtChg, lastHt - pos.Z, 0) - b).Length <= loopRadius)
							{
								break;
							}
						}
						num = i;
					}
					else
					{
						WVec wVec3 = new WVec(-relTarHgt, -relTarHorDist, 0);
						num = (((sbyte)wVec3.HorizontalLengthSquared != 0) ? wVec3.Yaw.Facing : vFacing);
						if (num < 0 && info.VerticalRateOfTurn.Facing < (sbyte)vFacing)
						{
							num = 0;
						}
					}
				}
				else
				{
					WVec wVec4 = new WVec(-relTarHgt, relTarHorDist, 0);
					num = (((sbyte)wVec4.HorizontalLengthSquared != 0) ? wVec4.Yaw.Facing : vFacing);
					if (num < 0 && info.VerticalRateOfTurn.Facing < (sbyte)vFacing)
					{
						num = 0;
					}
				}
			}
			else
			{
				WVec wVec5 = new WVec(-diffClfMslHgt - info.CruiseAltitude.Length, -speed, 0);
				num = (((sbyte)wVec5.HorizontalLengthSquared != 0) ? wVec5.Yaw.Facing : vFacing);
				if (-diffClfMslHgt > info.CruiseAltitude.Length)
				{
					num = -num;
				}
				num = num.Clamp(-info.VerticalRateOfTurn.Facing, info.VerticalRateOfTurn.Facing);
				ChangeSpeed();
			}
		}
		else
		{
			WVec wVec6 = new WVec(-diffClfMslHgt - info.CruiseAltitude.Length, -speed, 0);
			num = (((sbyte)wVec6.HorizontalLengthSquared != 0) ? wVec6.Yaw.Facing : vFacing);
			if (-diffClfMslHgt > info.CruiseAltitude.Length)
			{
				num = -num;
			}
			num = num.Clamp(-info.VerticalRateOfTurn.Facing, info.VerticalRateOfTurn.Facing);
			ChangeSpeed();
		}
		return num;
	}

	private WVec HomingTick(World world, in WVec tarDistVec, int relTarHorDist)
	{
		int predClfHgt = 0;
		int predClfDist = 0;
		int lastHtChg = 0;
		int lastHt = 0;
		if (info.TerrainHeightAware)
		{
			InclineLookahead(world, relTarHorDist, out predClfHgt, out predClfDist, out lastHtChg, out lastHt);
		}
		int diffClfMslHgt = predClfHgt - pos.Z;
		int num = (relTarHorDist - speed - info.Acceleration.Length).Clamp(0, relTarHorDist);
		int z = tarDistVec.Z;
		WVec wVec = tarDistVec + predVel;
		int num2 = ((wVec.HorizontalLengthSquared != 0L) ? wVec.Yaw.Facing : hFacing);
		int num3 = Util.NormalizeFacing(hFacing - num2);
		if (allowPassBy && num3 > 64 && num3 < 192)
		{
			num2 = (num2 + 128) & 0xFF;
			targetPassedBy = true;
		}
		else
		{
			targetPassedBy = false;
		}
		int desiredFacing = HomingInnerTick(predClfDist, diffClfMslHgt, relTarHorDist, lastHtChg, lastHt, z, vFacing, targetPassedBy);
		if (tarDistVec.HorizontalLength < speed * WAngle.FromFacing(vFacing).Cos() / 1024)
		{
			targetPassedBy = true;
		}
		if (info.Jammable && world.ActorsWithTrait<JamsMissiles>().Any(JammedBy))
		{
			num2 = hFacing + world.SharedRandom.Next(-info.JammedDiversionRange, info.JammedDiversionRange + 1);
			desiredFacing = vFacing + world.SharedRandom.Next(-info.JammedDiversionRange, info.JammedDiversionRange + 1);
		}
		else if (!args.GuidedTarget.IsValidFor(args.SourceActor))
		{
			num2 = hFacing;
		}
		hFacing = Util.TickFacing(hFacing, num2, info.HorizontalRateOfTurn.Facing);
		vFacing = Util.TickFacing(vFacing, desiredFacing, info.VerticalRateOfTurn.Facing);
		return new WVec(0, -1024 * speed, 0).Rotate(new WRot(WAngle.FromFacing(vFacing), WAngle.Zero, WAngle.Zero)).Rotate(new WRot(WAngle.Zero, WAngle.Zero, WAngle.FromFacing(hFacing))) / 1024;
	}

	public void Tick(World world)
	{
		ticks++;
		anim?.Tick();
		if (ticks == info.HomingActivationDelay + 1)
		{
			state = States.Homing;
			speed = velocity.Length;
			loopRadius = LoopRadius(speed, info.VerticalRateOfTurn.Facing);
		}
		if (rangeLimit >= WDist.Zero && distanceCovered > rangeLimit)
		{
			state = States.Freefall;
			velocity = new WVec(0, -speed, 0).Rotate(new WRot(WAngle.FromFacing(vFacing), WAngle.Zero, WAngle.Zero)).Rotate(new WRot(WAngle.Zero, WAngle.Zero, WAngle.FromFacing(hFacing)));
		}
		WPos a = targetPosition;
		if (args.GuidedTarget.IsValidFor(args.SourceActor) && lockOn)
		{
			a = (args.Weapon.TargetActorCenter ? args.GuidedTarget.CenterPosition : args.GuidedTarget.Positions.ClosestToIgnoringPath(args.Source)) + new WVec(WDist.Zero, WDist.Zero, info.AirburstAltitude);
		}
		WAngle wAngle = ((tarVel.HorizontalLengthSquared != 0L) ? tarVel.Yaw : WAngle.FromFacing(hFacing));
		tarVel = a - targetPosition;
		WAngle wAngle2 = ((tarVel.HorizontalLengthSquared != 0L) ? tarVel.Yaw : WAngle.FromFacing(hFacing));
		predVel = tarVel.Rotate(WRot.FromYaw(wAngle2 - wAngle));
		targetPosition = a;
		WVec tarDistVec = targetPosition + offset - pos;
		int length = tarDistVec.Length;
		int horizontalLength = tarDistVec.HorizontalLength;
		WVec move;
		if (state == States.Freefall)
		{
			move = FreefallTick();
		}
		else
		{
			move = HomingTick(world, in tarDistVec, horizontalLength);
		}
		renderFacing = new WVec(move.X, move.Y - move.Z, 0).Yaw;
		WPos start = pos;
		if (info.AllowSnapping && state != States.Freefall && length < move.Length)
		{
			pos = targetPosition + offset;
		}
		else
		{
			pos += move;
		}
		bool flag = false;
		if (info.Blockable && BlocksProjectiles.AnyBlockingActorsBetween(world, args.SourceActor.Owner, start, pos, info.Width, out var hit))
		{
			pos = hit;
			flag = true;
		}
		if (!string.IsNullOrEmpty(info.TrailImage) && --ticksToNextSmoke < 0 && (state != States.Freefall || info.TrailWhenDeactivated))
		{
			world.AddFrameEndTask((World w) =>
			{
				w.Add(new SpriteEffect(pos - ILSpyHelper_AsRefReadOnly(3 * move / 2), renderFacing, w, info.TrailImage, info.TrailSequences.Random(world.SharedRandom), trailPalette));
				static ref readonly T ILSpyHelper_AsRefReadOnly<T>(in T temp)
				{
					//ILSpy generated this function to help ensure overload resolution can pick the overload using 'in'
					return ref temp;
				}
			});
			ticksToNextSmoke = info.TrailInterval;
		}
		if (info.ContrailLength > 0)
		{
			contrail.Update(pos);
		}
		distanceCovered += new WDist(speed);
		CPos cell = world.Map.CellContaining(pos);
		WDist wDist = world.Map.DistanceAboveTerrain(pos);
		if (flag | (wDist.Length < 0 || length < info.CloseEnough.Length || (info.ExplodeWhenEmpty && rangeLimit >= WDist.Zero && distanceCovered > rangeLimit) || !world.Map.Contains(cell) || (!string.IsNullOrEmpty(info.BoundToTerrainType) && world.Map.GetTerrainInfo(cell).Type != info.BoundToTerrainType) || (wDist.Length < info.AirburstAltitude.Length && horizontalLength < info.CloseEnough.Length)))
		{
			Explode(world);
		}
	}

	private void Explode(World world)
	{
		if (info.ContrailLength > 0)
		{
			world.AddFrameEndTask((World w) =>
			{
				w.Add(new ContrailFader(pos, contrail));
			});
		}
		world.AddFrameEndTask((World w) =>
		{
			w.Remove(this);
		});
		if (ticks > info.Arm)
		{
			WarheadArgs warheadArgs = new WarheadArgs(args)
			{
				ImpactOrientation = new WRot(WAngle.Zero, WAngle.FromFacing(vFacing), WAngle.FromFacing(hFacing)),
				ImpactPosition = pos
			};
			args.Weapon.Impact(Target.FromPos(pos), warheadArgs);
		}
	}

	public IEnumerable<IRenderable> Render(WorldRenderer wr)
	{
		if (info.ContrailLength > 0)
		{
			yield return contrail;
		}
		if (anim == null)
		{
			yield break;
		}
		World world = args.SourceActor.World;
		if (world.FogObscures(pos))
		{
			yield break;
		}
		string text = info.Palette;
		if (text != null && info.IsPlayerPalette)
		{
			text += args.SourceActor.Owner.InternalName;
		}
		PaletteReference palette = wr.Palette(text);
		IRenderable[] array;
		if (info.Shadow)
		{
			WDist wDist = world.Map.DistanceAboveTerrain(pos);
			WPos wPos = pos - ILSpyHelper_AsRefReadOnly(new WVec(0, 0, wDist.Length));
			array = anim.Render(wPos, palette);
			foreach (IRenderable renderable in array)
			{
				yield return ((IModifyableRenderable)renderable).WithTint(in shadowColor, ((IModifyableRenderable)renderable).TintModifiers | TintModifiers.ReplaceColor).WithAlpha(shadowAlpha);
			}
		}
		array = anim.Render(pos, palette);
		for (int i = 0; i < array.Length; i++)
		{
			yield return array[i];
		}
		static ref readonly T ILSpyHelper_AsRefReadOnly<T>(in T temp)
		{
			//ILSpy generated this function to help ensure overload resolution can pick the overload using 'in'
			return ref temp;
		}
	}
}

